/// "Photo: Author · Licence · Wikimedia Commons" for a recipe picture, or null when unknown.
String? photoCreditFor(String? url) {
  if (url == null) return null;
  final c = photoCredits[url];
  return c == null ? null : 'Photo: $c · Wikimedia Commons';
}
